// regra — erro vira registro e e-mail, nunca só uma linha de log: scripts/20_monitor.py:600-617
// O Error Trigger entrega `execution` (falha no meio do fluxo) ou `trigger`
// (falha no próprio gatilho, sem execução): os dois viram o mesmo contexto.
const e = $input.first().json || {};
const exec = e.execution || {};
const wf = e.workflow || {};
const nome = String(wf.name || 'fluxo desconhecido');
const codigo = (nome.match(/^W\d{2}/) || [nome])[0];
const erro = exec.error || (e.trigger && e.trigger.error) || {};
const mensagem = String(erro.message || 'erro sem mensagem').slice(0, 500);
const execucaoId = exec.id != null ? String(exec.id) : '';
const url = exec.url || '';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corpo = [
  `<p><b>${esc(nome)}</b> falhou${exec.lastNodeExecuted ? ' no nó <b>' + esc(exec.lastNodeExecuted) + '</b>' : ''}.</p>`,
  `<p>${esc(mensagem)}</p>`,
  url ? `<p><a href="${esc(url)}">Abrir a execução ${esc(execucaoId)} no n8n</a></p>` : '<p>Falha no gatilho: não há execução para abrir.</p>',
  `<p>Modo: ${esc(exec.mode || 'gatilho')}. Iguais nesta hora não geram outro e-mail (anti-tempestade).</p>`,
].join('');
return [{ json: {
  workflow: codigo, workflow_nome: nome, execucao_id: execucaoId, url, mensagem,
  ultimo_no: exec.lastNodeExecuted || null, corpo_html: corpo,
} }];
